package vn.covie.realtime; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import vn.covie.auth.security.CurrentActorProvider; @RestController public class MeEventStreamController {private final CurrentActorProvider actors;private final SseConnectionRegistry registry;public MeEventStreamController(CurrentActorProvider a,SseConnectionRegistry r){actors=a;registry=r;}@GetMapping(value="/api/v1/me/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE)public ResponseEntity<SseEmitter> events(){return ResponseEntity.ok().cacheControl(CacheControl.noStore().cachePrivate()).header("X-Accel-Buffering","no").body(registry.register(actors.currentActor().userId()));}}
